/*
 * Minimal curses declarations for building without ncurses headers.
 * Only the subset used by cmatrix is declared here.
 */
#ifndef CM_CURSES_DECLS_H
#define CM_CURSES_DECLS_H

#include <stdarg.h>
#include <stdio.h>

typedef unsigned int chtype;
typedef chtype attr_t;
typedef struct _win_st WINDOW;
typedef struct screen SCREEN;
typedef unsigned int wint_t_stub;

/* Globals kept by ncurses */
extern int COLS;
extern int LINES;
extern WINDOW *stdscr;

/* Colors */
#define COLOR_BLACK   0
#define COLOR_RED     1
#define COLOR_GREEN   2
#define COLOR_YELLOW  3
#define COLOR_BLUE    4
#define COLOR_MAGENTA 5
#define COLOR_CYAN    6
#define COLOR_WHITE   7

/* Attributes (matching ncurses layout) */
#define NCURSES_ATTR_SHIFT 8
#define A_NORMAL     0U
#define A_ATTRIBUTES 0xffffff00U
#define A_BOLD       (1U << 21)
#define A_ALTCHARSET (1U << 22)
#define A_REVERSE    (1U << 18)
#define A_UNDERLINE  (1U << 17)

/* Return values */
#define TRUE  1
#define FALSE 0
#define OK    0
#define ERR  (-1)

/* Key codes */
#define KEY_RESIZE 0632
#define KEY_UP     0403
#define KEY_DOWN   0402

/* Function prototypes we use */
extern WINDOW *initscr(void);
extern int endwin(void);
extern int cbreak(void);
extern int nocbreak(void);
extern int noecho(void);
extern int echo(void);
extern int raw(void);
extern int keypad(WINDOW *win, int bf);
extern int nodelay(WINDOW *win, int bf);
extern int leaveok(WINDOW *win, int bf);
extern int scrollok(WINDOW *win, int bf);
extern int curs_set(int visibility);
extern int refresh(void);
extern int wrefresh(WINDOW *win);
extern int clear(void);
extern int erase(void);
extern int move(int y, int x);
extern int wmove(WINDOW *win, int y, int x);
extern int attron(int attrs);
extern int attroff(int attrs);
extern int attrset(int attrs);
extern int wattron(WINDOW *win, int attrs);
extern int wattroff(WINDOW *win, int attrs);
extern int start_color(void);
extern int has_colors(void);
extern int init_pair(short pair, short f, short b);
extern int use_default_colors(void);
extern int mvprintw(int y, int x, const char *fmt, ...);
extern int printw(const char *fmt, ...);
extern int mvaddstr(int y, int x, const char *str);
extern int addstr(const char *str);
extern int mvaddch(int y, int x, chtype ch);
extern int addch(chtype ch);
extern int getch(void);
extern int wgetch(WINDOW *win);
extern int timeout(int delay);
extern int wtimeout(WINDOW *win, int delay);
extern int napms(int ms);
extern int resetty(void);
extern int savetty(void);
extern int flushinp(void);
extern int clearok(WINDOW *win, int bf);
extern SCREEN *newterm(const char *type, FILE *outfd, FILE *infd);
extern SCREEN *set_term(SCREEN *);
extern void delscreen(SCREEN *);

/* In wide ncurses COLOR_PAIR is an exported function. */
extern chtype COLOR_PAIR(int n);

/* Wide character support */
extern int mvaddnwstr(int y, int x, const wchar_t *wstr, int n);
extern int addnwstr(const wchar_t *wstr, int n);

#endif
EOF
