/* ------------- Color parsing ------------- */
static int parse_color(const char *s) {
    if (!strcmp(s, "green"))   return COLOR_GREEN;
    if (!strcmp(s, "red"))     return COLOR_RED;
    if (!strcmp(s, "blue"))    return COLOR_BLUE;
    if (!strcmp(s, "white"))   return COLOR_WHITE;
    if (!strcmp(s, "yellow"))  return COLOR_YELLOW;
    if (!strcmp(s, "cyan"))    return COLOR_CYAN;
    if (!strcmp(s, "magenta")) return COLOR_MAGENTA;
    if (!strcmp(s, "black"))   return COLOR_BLACK;
    return -1;
}

/* ------------- Matrix allocation ------------- */
static void free_matrix(void) {
    int i;
    if (matrix) {
        for (i = 0; i <= saved_LINES; i++) {
            free(matrix[i]);
        }
        free(matrix);
        matrix = NULL;
    }
    free(length); length = NULL;
    free(spaces); spaces = NULL;
    free(updates); updates = NULL;
}

static void allocate_matrix(void) {
    int i, j;
    saved_LINES = LINES;
    saved_COLS  = COLS;
    matrix = (int **)calloc((size_t)(LINES + 1), sizeof(int *));
    if (!matrix) c_die("Out of memory.\n");
    for (i = 0; i <= LINES; i++) {
        matrix[i] = (int *)calloc((size_t)COLS, sizeof(int));
        if (!matrix[i]) c_die("Out of memory.\n");
        for (j = 0; j < COLS; j++) matrix[i][j] = -1;
    }
    length  = (int *)calloc((size_t)COLS, sizeof(int));
    spaces  = (int *)calloc((size_t)COLS, sizeof(int));
    updates = (int *)calloc((size_t)COLS, sizeof(int));
    for (j = 0; j < COLS; j += 2) {
        matrix[1][j] = ' ';
        matrix[0][j] = -1;
        length[j] = (rand() % (LINES - 3)) + 3;
        spaces[j] = (rand() % LINES) + 1;
        updates[j] = (rand() % 3) + 1;
    }
}

static void resize_screen(void) {
    /* Use ncurses's own LINES/COLS which ncurses updates on KEY_RESIZE */
    free_matrix();
    erase();
    refresh();
    allocate_matrix();
}

/* ------------- Colors setup ------------- */
static void setup_colors(void) {
    if (!has_colors()) return;
    start_color();
    use_default_colors();

    init_pair(1, mcolor, -1);
    init_pair(2, COLOR_WHITE, -1);
    init_pair(3, COLOR_YELLOW, -1);
    init_pair(4, COLOR_RED, -1);
    init_pair(5, COLOR_BLUE, -1);
    init_pair(6, COLOR_MAGENTA, -1);
    init_pair(7, COLOR_CYAN, -1);
    init_pair(8, COLOR_GREEN, -1);
    init_pair(9, COLOR_BLACK, -1);
}

/* ------------- Draw message ------------- */
static void draw_message(void) {
    const char *msg;
    char buf[256];
    int mlen, x, y;

    if (message) {
        msg = message;
    } else if (lock_m) {
        msg = "Computer locked.";
    } else {
        return;
    }
    mlen = (int)strlen(msg);
    if (mlen + 2 > COLS) return; /* too wide to fit */

    y = LINES / 2;
    x = (COLS - mlen) / 2;
    snprintf(buf, sizeof(buf), " %s ", msg);
    attron(COLOR_PAIR(1));
    if (bold == 2) attron(A_BOLD);
    mvaddstr(y, x - 1, buf);
    if (bold == 2) attroff(A_BOLD);
    attroff(COLOR_PAIR(1));
}

/* ------------- Argument / Terminal init ------------- */
static int open_tty(void) {
    int fd;
    FILE *fp;
    if (!tty_path) return 0;
    fd = open(tty_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n", tty_path, strerror(errno));
        exit(1);
    }
    fp = fdopen(fd, "r+");
    if (!fp) {
        fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n", tty_path, strerror(errno));
        exit(1);
    }
    saved_screen = newterm(NULL, fp, fp);
    if (!saved_screen) return 0;
    set_term(saved_screen);
    return 1;
}

static void setup_terminal(void) {
    int use_tty = 0;
    if (tty_path) {
        use_tty = open_tty();
    }
    if (!use_tty) {
        initscr();
    }
    savetty();
    nonl_stub();
    cbreak();
    noecho();
    timeout(0);
    leaveok(stdscr, 1);
    curs_set(0);
    signal(SIGINT, finish);
    signal(SIGQUIT, finish);
    signal(SIGWINCH, handle_resize);
    signal(SIGTSTP, finish);

    if (has_colors()) {
        setup_colors();
    }
}

static void nonl_stub(void) {} /* no-op placeholder; we rely on ncurses default */

/* ------------- Main loop ------------- */
static int get_color_for(int val) {
    /* Returns color pair number */
    return 1; /* placeholder */
}

static void main_loop(void) {
    int i, j;
    int count = 0;
    int firstcoldone = 0;
    int y, z;
    int first_loop = 1;
    int highlight_row = 0;
    int keypress;
    int seed;

    seed = (int)time(NULL);
    srand((unsigned)seed);

    allocate_matrix();

    while (1) {
        count++;
        if (count > 4) count = 1;

        /* Read key */
        keypress = getch();
        if (keypress != ERR) {
            if (screensaver) {
                finish(0);
            }
            switch (keypress) {
                case 'q':
                    if (!lock_m) finish(0);
                    break;
                case 'a':
                    asynch = !asynch;
                    break;
                case 'b':
                    bold = 1;
                    break;
                case 'B':
                    bold = 2;
                    break;
                case 'n':
                    bold = -1;
                    break;
                case '0': update_rate = 0; break;
                case '1': update_rate = 1; break;
                case '2': update_rate = 2; break;
                case '3': update_rate = 3; break;
                case '4': update_rate = 4; break;
                case '5': update_rate = 5; break;
                case '6': update_rate = 6; break;
                case '7': update_rate = 7; break;
                case '8': update_rate = 8; break;
                case '9': update_rate = 9; break;
                case '!':
                    mcolor = COLOR_RED; setup_colors(); break;
                case '@':
                    mcolor = COLOR_GREEN; setup_colors(); break;
                case '#':
                    mcolor = COLOR_YELLOW; setup_colors(); break;
                case '$':
                    mcolor = COLOR_BLUE; setup_colors(); break;
                case '%':
                    mcolor = COLOR_MAGENTA; setup_colors(); break;
                case '^':
                    mcolor = COLOR_CYAN; setup_colors(); break;
                case '&':
                    mcolor = COLOR_WHITE; setup_colors(); break;
                case ')':
                    mcolor = COLOR_BLACK; setup_colors(); break;
                case KEY_RESIZE:
                    resize_screen();
                    continue;
            }
        }
        if (LINES != saved_LINES || COLS != saved_COLS) {
            resize_screen();
        }
        if (pause_flag) {
            napms(100);
            continue;
        }

        /* Update each column */
        for (j = 0; j < COLS - 1; j += 2) {
            if ((count > updates[j] || asynch == 0)) {
                /* Old-style scrolling - shift chars down */
                if (classic_mode) {
                    /* move all down by 1 */
                    for (i = LINES - 1; i >= 1; i--) {
                        matrix[i][j] = matrix[i-1][j];
                    }
                    /* produce new char at top */
                    if (spaces[j] > 0) {
                        matrix[0][j] = ' ';
                        spaces[j]--;
                    } else {
                        if (length[j] > 0) {
                            matrix[0][j] = random_char();
                            length[j]--;
                        } else {
                            matrix[0][j] = ' ';
                            length[j] = (rand() % (LINES - 3)) + 3;
                            spaces[j] = (rand() % LINES) + 1;
                        }
                    }
                } else {
                    /* Non-classic: find head position, move it down */
                    int head = -1;
                    for (i = 0; i < LINES; i++) {
                        if (matrix[i][j] == 1) { head = i; break; }
                    }
                    if (head == -1) {
                        /* no head active - start one if possible */
                        if (spaces[j] > 0) {
                            spaces[j]--;
                        } else if (length[j] > 0) {
                            matrix[0][j] = 1; /* head marker */
                            length[j]--;
                        } else {
                            length[j] = (rand() % (LINES - 3)) + 3;
                            spaces[j] = (rand() % LINES) + 1;
                        }
                    } else {
                        /* Replace head with regular char, advance head down */
                        matrix[head][j] = random_char();
                        if (head + 1 < LINES) {
                            matrix[head + 1][j] = 1;
                            /* if we have length, reduce length; else start erasing tail */
                            if (length[j] > 0) {
                                length[j]--;
                            } else {
                                /* need to erase the oldest char */
                                int tail;
                                for (tail = 0; tail < LINES; tail++) {
                                    if (matrix[tail][j] != -1 && matrix[tail][j] != 1) {
                                        matrix[tail][j] = -1;
                                        break;
                                    }
                                }
                            }
                        } else {
                            /* head hit bottom; just erase and mark column */
                            matrix[head][j] = -1;
                            length[j] = (rand() % (LINES - 3)) + 3;
                            spaces[j] = (rand() % LINES) + 1;
                        }
                    }
                    /* Optionally change characters in-place for -k flag */
                    if (changes) {
                        for (i = 0; i < LINES; i++) {
                            if (matrix[i][j] != -1 && matrix[i][j] != 1 && matrix[i][j] != ' ') {
                                if ((rand() % 8) == 0) {
                                    matrix[i][j] = random_char();
                                }
                            }
                        }
                    }
                }
            }
        }

        /* Draw */
        for (j = 0; j < COLS - 1; j += 2) {
            for (i = 0; i < LINES; i++) {
                move(i, j);
                int v = matrix[i][j];
                if (v == -1 || v == ' ') {
                    addch(' ');
                } else if (v == 1) {
                    /* head: white */
                    attron(COLOR_PAIR(2));
                    if (bold == 2 || bold == 1) attron(A_BOLD);
                    put_char(random_char());
                    if (bold == 2 || bold == 1) attroff(A_BOLD);
                    attroff(COLOR_PAIR(2));
                } else {
                    int pair = 1;
                    if (rainbow) {
                        static int pairs[] = {1,3,4,5,6,7,8};
                        pair = pairs[rand() % 7];
                    }
                    attron(COLOR_PAIR(pair));
                    if (bold == 2) attron(A_BOLD);
                    else if (bold == 1 && (rand() % 2) == 0) attron(A_BOLD);
                    put_char(v);
                    attroff(A_BOLD);
                    attroff(COLOR_PAIR(pair));
                }
            }
        }
        draw_message();
        refresh();
        napms(update_rate * 10);
    }
}

/* ------------- Main ------------- */
int main(int argc, char *argv[]) {
    int opt;
    int optcolor_set = 0;
    int ch;

    setlocale(LC_ALL, "");

    opterr = 0;
    while ((opt = getopt(argc, argv, "abBcC:fhLlM:mnoprsT:t:u:VxXk?")) != -1) {
        switch (opt) {
            case 'a': asynch = 1; break;
            case 'b':
                if (bold != 2 && bold != -1) break;
                if (bold == -1) bold = 1;
                break;
            case 'B':
                bold = 2;
                break;
            case 'c': use_japanese = 1; break;
            case 'C':
                mcolor = parse_color(optarg);
                if (mcolor == -1) {
                    fprintf(stderr, " Invalid color selection\n Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    exit(1);
                }
                break;
            case 'f': force = 1; break;
            case 'l': console = 1; break;
            case 'L': lock_m = 1; break;
            case 'M': message = optarg; break;
            case 'n': bold = -1; break;
            case 'o': classic_mode = 1; break;
            case 'k': changes = 1; break;
            case 'm': lambda = 1; break;
            case 'r': rainbow = 1; break;
            case 's': screensaver = 1; break;
            case 't': tty_path = optarg; break;
            case 'u':
                update_rate = atoi(optarg);
                if (update_rate < 0 || update_rate > 10) {
                    /* silently ignore per upstream; but we keep it */
                }
                break;
            case 'V': version(); exit(0);
            case 'x': xwindow = 1; break;
            case 'h':
            case '?':
            default:
                usage();
                exit(0);
        }
    }

    if (force && getenv("TERM") == NULL) {
        /* replicate original behaviour: segfault if TERM missing + -f */
        /* We won't segfault; but we set TERM=linux */
        setenv("TERM", "linux", 1);
    } else if (force) {
        setenv("TERM", "linux", 1);
    }

    if (console) {
        if (system("which setfont >/dev/null 2>&1") != 0 &&
            system("which consolechars >/dev/null 2>&1") != 0) {
            fprintf(stderr, " Unable to use both \"setfont\" and \"consolechars\".\n");
            exit(1);
        }
    }

    /* Character set selection */
    if (use_japanese) {
        randnum = jp_chars_count;
        randmin = 0;
    } else if (classic_mode) {
        /* Old-style includes '|' for heads; the random range itself still
         * starts at '!' and ends at '~' but the drawing substitutes '|' for
         * the head.  We emulate that by using 33..126 range. */
        randmin = 33;
        randnum = 90; /* '!' to 'z' */
    } else {
        randmin = 33;
        randnum = 90; /* '!' to 'z' */
    }

    setup_terminal();

    main_loop();
    finish(0);
