/* Writes wide char as UTF-8 and prints via addstr. */
static void add_widechar(wchar_t wc) {
    char buf[8];
    int n = 0;
    unsigned int c = (unsigned int)wc;
    if (c < 0x80) {
        buf[n++] = (char)c;
