};
static const int jp_chars_count = (int)(sizeof(jp_chars)/sizeof(jp_chars[0]));

/* Writes wide char as UTF-8 and prints via addstr. */
static void add_widechar(wchar_t wc) {
    char buf[8];
    int n = 0;
    unsigned int c = (unsigned int)wc;
    if (c < 0x80) {
        buf[n++] = (char)c;
    } else if (c < 0x800) {
        buf[n++] = (char)(0xC0 | (c >> 6));
        buf[n++] = (char)(0x80 | (c & 0x3F));
    } else if (c < 0x10000) {
        buf[n++] = (char)(0xE0 | (c >> 12));
        buf[n++] = (char)(0x80 | ((c >> 6) & 0x3F));
        buf[n++] = (char)(0x80 | (c & 0x3F));
    } else {
        buf[n++] = (char)(0xF0 | (c >> 18));
        buf[n++] = (char)(0x80 | ((c >> 12) & 0x3F));
        buf[n++] = (char)(0x80 | ((c >> 6) & 0x3F));
        buf[n++] = (char)(0x80 | (c & 0x3F));
    }
    buf[n] = '\0';
    addstr(buf);
}

/* Random character according to current character set */
static int random_char(void) {
    if (use_japanese) {
        /* pick random from jp_chars array */
        return 0x80000000 | (unsigned)jp_chars[rand() % jp_chars_count];
    } else {
        return randmin + rand() % randnum;
    }
}

/* Output a "cell" character at current cursor (for display) */
static void put_char(int val) {
    if (val == -1 || val == ' ') {
        addch(' ');
        return;
    }
    if (lambda && val != 1) {
        /* Print a λ (U+03BB) */
        add_widechar(0x03BB);
        return;
    }
    if (val & 0x80000000) {
        add_widechar((wchar_t)(val & 0x7FFFFFFF));
    } else {
        addch((chtype)val);
    }
}

/* ------------- Signal / cleanup handling ------------- */
static void finish(int sig) {
    (void)sig;
    curs_set(1);
    clear();
    refresh();
    resetty();
    endwin();
    if (console) {
        /* Run consolechars/setfont to restore console font */
#ifdef HAVE_CONSOLECHARS
        system("consolechars -d");
#endif
    }
    exit(0);
}

static void c_die(const char *fmt, ...) {
    va_list ap;
    resetty();
    endwin();
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    exit(1);
}

static void handle_resize(int sig) {
    (void)sig;
