    col_upd   = (int *)calloc((size_t)COLS, sizeof(int));
    for (j = 0; j < COLS; j += 2) {
        col_len[j]   = (LINES > 4) ? ((rand() % (LINES - 3)) + 3) : 3;
        col_space[j] = (rand() % LINES) + 1;
        col_upd[j]   = (rand() % 3) + 1;
    }
}

static void resize_screen(void) {
    free_matrix();
    erase();
    refresh();
    allocate_matrix();
}

/* -------------------- Random character generation -------------------- */
static int random_char_value(void) {
    if (opt_japanese) {
        return CELL_WIDECHAR_FLAG | (int)jp_chars[rand() % JP_N];
    }
    return 33 + (rand() % 90);
}

/* Draw a single cell value at the current cursor position. */
static void put_value(int v) {
    if (v == CELL_EMPTY) {
        addch(' ');
        return;
    }
    if (v == CELL_HEAD) {
        /* Should have been substituted already */
        addch(' ');
        return;
    }
    if (opt_lambda) {
        write_utf8(0x03BB); /* λ */
        return;
    }
    if (v & CELL_WIDECHAR_FLAG) {
        write_utf8((unsigned int)(v & ~CELL_WIDECHAR_FLAG));
    } else {
        addch((chtype)v);
    }
}

/* -------------------- Message overlay -------------------- */
static void draw_message(void) {
    const char *msg = NULL;
    char padded[256];
    int mlen, x, y;
    if (opt_message) msg = opt_message;
    else if (opt_lock) msg = "Computer locked.";
    else return;
    mlen = (int)strlen(msg);
    if (mlen + 2 > COLS) return;
    y = LINES / 2;
    x = (COLS - mlen) / 2;
    snprintf(padded, sizeof(padded), " %s ", msg);
    attron(COLOR_PAIR(1));
    if (opt_bold == 2) attron(A_BOLD);
    mvaddstr(y, x - 1, padded);
    if (opt_bold == 2) attroff(A_BOLD);
    attroff(COLOR_PAIR(1));
}

/* -------------------- Cleanup and signal handlers -------------------- */
static void cleanup(void) {
    curs_set(1);
    clear();
    refresh();
    resetty();
    endwin();
}

static void finish(int sig) {
    (void)sig;
    cleanup();
    exit(0);
}

static void handle_resize(int sig) {
    (void)sig;
    /* ncurses will send KEY_RESIZE via getch() */
}

static void c_die(const char *fmt, ...) {
    va_list ap;
    cleanup();
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    exit(1);
}

/* -------------------- Terminal open via alternate tty -------------------- */
static void open_user_tty(void) {
    int fd;
    FILE *fp;
    if (!opt_tty) return;
    fd = open(opt_tty, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n",
                opt_tty, strerror(errno));
        exit(1);
    }
    fp = fdopen(fd, "r+");
    if (!fp) {
        fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n",
                opt_tty, strerror(errno));
        exit(1);
    }
    if (newterm(NULL, fp, fp) == NULL) {
        fprintf(stderr, "cmatrix: error: can't initialize terminal on '%s'.\n",
                opt_tty);
        exit(1);
    }
}

/* -------------------- Main animation loop -------------------- */
static void run_main_loop(void) {
    int i, j;
    int count = 0;
    int seed = (int)time(NULL) ^ (int)getpid();
    srand((unsigned)seed);

    allocate_matrix();

    while (1) {
        int keypress;
        count = (count % 4) + 1;

        keypress = getch();
        if (keypress != ERR) {
            if (opt_screensaver) { finish(0); }
            switch (keypress) {
                case 'q':
                    if (!opt_lock) finish(0);
                    break;
                case 'a':
                    opt_async = !opt_async;
                    break;
                case 'b':
                    opt_bold = 1;
                    break;
                case 'B':
                    opt_bold = 2;
                    break;
                case 'n':
                    opt_bold = -1;
                    break;
                case '0': opt_update = 0; break;
                case '1': opt_update = 1; break;
                case '2': opt_update = 2; break;
                case '3': opt_update = 3; break;
                case '4': opt_update = 4; break;
                case '5': opt_update = 5; break;
                case '6': opt_update = 6; break;
                case '7': opt_update = 7; break;
                case '8': opt_update = 8; break;
                case '9': opt_update = 9; break;
                case '!': opt_mcolor = COLOR_RED;     setup_colors(); break;
                case '@': opt_mcolor = COLOR_GREEN;   setup_colors(); break;
                case '#': opt_mcolor = COLOR_YELLOW;  setup_colors(); break;
                case '$': opt_mcolor = COLOR_BLUE;    setup_colors(); break;
                case '%': opt_mcolor = COLOR_MAGENTA; setup_colors(); break;
                case '^': opt_mcolor = COLOR_CYAN;    setup_colors(); break;
                case '&': opt_mcolor = COLOR_WHITE;   setup_colors(); break;
                case ')': opt_mcolor = COLOR_BLACK;   setup_colors(); break;
                case 'p':
                    pause_flag = !pause_flag;
                    break;
                case KEY_RESIZE:
                    resize_screen();
                    continue;
                default:
                    break;
            }
        }

        if (LINES != saved_lines || COLS != saved_cols) {
            resize_screen();
        }

        if (pause_flag) {
            napms(80);
            continue;
        }

        /* Update each column (even columns only; every other column stays blank) */
        for (j = 0; j < COLS - 1; j += 2) {
            if (opt_async && count <= col_upd[j]) continue;

            if (opt_classic) {
                /* shift every row down by one */
                for (i = LINES - 1; i >= 1; i--) M[i][j] = M[i-1][j];
                if (col_space[j] > 0) {
                    M[0][j] = CELL_EMPTY;
                    col_space[j]--;
                } else if (col_len[j] > 0) {
                    M[0][j] = random_char_value();
                    col_len[j]--;
                } else {
                    M[0][j] = CELL_EMPTY;
                    col_len[j]   = (rand() % (LINES - 3)) + 3;
                    col_space[j] = (rand() % LINES) + 1;
                }
            } else {
                int head = -1;
                for (i = 0; i < LINES; i++) {
                    if (M[i][j] == CELL_HEAD) { head = i; break; }
                }
                if (head == -1) {
                    if (col_space[j] > 0) {
                        col_space[j]--;
                    } else if (col_len[j] > 0) {
                        M[0][j] = CELL_HEAD;
                        col_len[j]--;
                    } else {
                        col_len[j]   = (rand() % (LINES - 3)) + 3;
                        col_space[j] = (rand() % LINES) + 1;
                    }
                } else {
                    /* Turn head into a char, advance head one row. */
                    M[head][j] = random_char_value();
                    if (head + 1 < LINES) {
                        M[head + 1][j] = CELL_HEAD;
                        if (col_len[j] > 0) {
                            col_len[j]--;
                        } else {
                            /* erase oldest trail char */
                            for (i = 0; i < LINES; i++) {
                                if (M[i][j] != CELL_EMPTY && M[i][j] != CELL_HEAD) {
                                    M[i][j] = CELL_EMPTY;
                                    break;
                                }
                            }
                        }
                    } else {
                        /* head reached the bottom: eat tail and restart */
                        int tail = -1;
                        for (i = 0; i < LINES; i++) {
                            if (M[i][j] != CELL_EMPTY) { tail = i; break; }
                        }
                        if (tail >= 0) M[tail][j] = CELL_EMPTY;
                        /* No new head this tick; schedule next drop */
                        if (col_len[j] == 0 && col_space[j] == 0) {
                            col_len[j]   = (rand() % (LINES - 3)) + 3;
                            col_space[j] = (rand() % LINES) + 1;
                        }
                    }
                }
                if (opt_changes) {
                    for (i = 0; i < LINES; i++) {
                        int v = M[i][j];
                        if (v != CELL_EMPTY && v != CELL_HEAD) {
                            if ((rand() & 7) == 0) M[i][j] = random_char_value();
                        }
                    }
                }
            }
        }

        /* Draw */
        for (j = 0; j < COLS - 1; j += 2) {
            for (i = 0; i < LINES; i++) {
                int v = M[i][j];
                move(i, j);
                if (v == CELL_EMPTY) {
                    addch(' ');
                    continue;
                }
                if (v == CELL_HEAD) {
                    attron(COLOR_PAIR(2));
                    if (opt_bold == 1 || opt_bold == 2) attron(A_BOLD);
                    if (opt_classic) {
                        addch('|');
                    } else {
                        /* Display a random character in head color */
                        int rv = random_char_value();
                        if (opt_lambda) write_utf8(0x03BB);
                        else if (rv & CELL_WIDECHAR_FLAG) write_utf8((unsigned)(rv & ~CELL_WIDECHAR_FLAG));
                        else addch((chtype)rv);
                    }
                    if (opt_bold == 1 || opt_bold == 2) attroff(A_BOLD);
                    attroff(COLOR_PAIR(2));
                    continue;
                }
                {
                    int pair = 1;
                    int make_bold = 0;
                    if (opt_rainbow) {
                        static int pairs[] = {1,3,4,5,6,7,8};
                        pair = pairs[rand() % 7];
                    }
                    if (opt_bold == 2) make_bold = 1;
                    else if (opt_bold == 1 && (rand() & 1)) make_bold = 1;
                    attron(COLOR_PAIR(pair));
                    if (make_bold) attron(A_BOLD);
                    put_value(v);
                    if (make_bold) attroff(A_BOLD);
                    attroff(COLOR_PAIR(pair));
                }
            }
        }

        draw_message();
        refresh();
        napms(opt_update * 10);
    }
}

/* -------------------- Argument parsing -------------------- */
static void parse_options(int argc, char *argv[]) {
    int opt;
    opterr = 0;
    while ((opt = getopt(argc, argv, "abBcC:fhLlM:mnorst:u:Vxk?")) != -1) {
        switch (opt) {
            case 'a': opt_async = 1; break;
            case 'b':
                if (opt_bold != 2) opt_bold = 1;
                break;
            case 'B': opt_bold = 2; break;
            case 'c': opt_japanese = 1; break;
            case 'C':
                opt_mcolor = parse_color(optarg);
                if (opt_mcolor < 0) {
                    fprintf(stderr, " Invalid color selection\n");
                    fprintf(stderr, " Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    exit(1);
                }
                break;
            case 'f': opt_force = 1; break;
            case 'h': usage(); exit(0);
            case 'L': opt_lock = 1; break;
            case 'l': opt_console = 1; break;
            case 'M': opt_message = optarg; break;
            case 'm': opt_lambda = 1; break;
            case 'n': opt_bold = -1; break;
            case 'o': opt_classic = 1; break;
            case 'r': opt_rainbow = 1; break;
            case 's': opt_screensaver = 1; break;
            case 't': opt_tty = optarg; break;
            case 'u':
                if (optarg) {
                    int u = atoi(optarg);
                    if (u >= 0 && u <= 10) opt_update = u;
                }
                break;
            case 'V': version(); exit(0);
            case 'x': opt_xwindow = 1; break;
            case 'k': opt_changes = 1; break;
            case '?':
            default:
                usage();
                exit(0);
        }
    }
}

int main(int argc, char *argv[]) {
    setlocale(LC_ALL, "");
    parse_options(argc, argv);

    if (opt_console) {
        /* Check for setfont/consolechars availability. */
        int has_setfont      = (system("which setfont      >/dev/null 2>&1") == 0);
        int has_consolechars = (system("which consolechars >/dev/null 2>&1") == 0);
        if (!has_setfont && !has_consolechars) {
            fprintf(stderr, " Unable to use both \"setfont\" and \"consolechars\".\n");
            exit(1);
        }
    }

    if (opt_force && getenv("TERM")) {
        setenv("TERM", "linux", 1);
    }

    open_user_tty();
    if (!opt_tty) {
        initscr();
    }
    savetty();
    cbreak();
    noecho();
    timeout(0);
    leaveok(stdscr, 1);
    curs_set(0);

    signal(SIGINT,  finish);
    signal(SIGQUIT, finish);
    signal(SIGTSTP, finish);
    signal(SIGWINCH, handle_resize);

    setup_colors();

    run_main_loop();
    finish(0);
    return 0;
}
